@dataclass(frozen=True)
class Certificate:
    certificate_no: str
    subcontractor: str
    coverage_from: date | None
    coverage_to: date | None
    source: SourceReference
    raw_record: CSVRow | None = None


@dataclass(frozen=True)
class SubcontractorCase:
    period: AuditPeriod
    payment: SubcontractorPayment
