{"push_source": {"url": "https://raw.githubusercontent.com/entireio/cli/c398a36170d08a9613a90867a29988f07bf030e3/cmd/entire/cli/strategy/manual_commit_push.go", "source": "package strategy

import (
	"context"
	"errors"
