import concurrent.futures,json,re,urllib.request
revision='c398a36170d08a9613a90867a29988f07bf030e3'
paths=['cmd/entire/cli/strategy/push_common.go','docs/security-and-privacy.md']
def read(path):
    url=f'https://raw.githubusercontent.com/entireio/cli/{revision}/{path}'
    try:
        with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'insurance01-read-only-evidence-review'}),timeout=30) as response:
            lines=response.read().decode().splitlines()
        selected=set()
        pattern=r'func batchPushRefs|func resolvePushSettings|pushDisabled|push_sessions|ENTIRE_.*PUSH|session.*filter|public|private|PII|redact|secret|transcript'
        for i,line in enumerate(lines):
            if re.search(pattern,line,re.I if path.endswith('.md') else 0):
                selected.update(range(max(0,i-3),min(len(lines),i+(20 if path.endswith('.go') else 3))))
        return {'path':path,'url':url,'lines':len(lines),'selected_lines':'\n'.join(f'{i+1}: {lines[i]}' for i in sorted(selected))}
    except Exception as exc:
        return {'path':path,'error':str(exc)}
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
    print(json.dumps(list(pool.map(read,paths))))
