                if r["position"] in {"Catering Lead","Event Cook","Event Server"}: pending[key]=money(r["wages_paid"])
                else:
                    assert r["position"] in {"Sous Chef","Line Cook","Server","Dishwasher"}
                    expected[key]["F-710"]+=money(r["wages_paid"])
        elif "law office" in business:
            visitors={r["employee_id"] for r in rows(directory/"site-signin-log.csv")}
            for key,r in by_id.items():
                if key in visitors: pending[key]=money(r["wages_paid"])
                else: expected[key]["C-110"]+=money(r["wages_paid"])
        else:
            assert "has not filed an election of exclusion" in business and "on top of" in notes and "never goes to jobs" in notes
            for key,r in by_id.items():
                code="C-110" if r["position"]=="Office Administrator" else "E-510"
                expected[key][code]+=money(r["wages_paid"])
                allowance=money(r["travel_allowance_paid"]); days=int(r["travel_days"]); controls["basis"]+=allowance
                if not days and allowance:
                    controls["open_basis"]+=allowance
                    line=next(v for v in entry["adjustments"]["lines"] if v["adjustment_id"]=="travel:"+key)
                    assert line["status"]=="OPEN" and money(line["payroll_added"])==0 and money(line["proposal"]["payroll_added"])==allowance
                else:
                    excluded=min(allowance,Decimal("47")*days); addition=allowance-excluded
                    controls["nonpayroll"]+=excluded; controls["added"]+=addition
                    if addition: expected[key][code]+=addition
        expected_codes=defaultdict(lambda:Decimal("0.00"))
        encoded={e["employee_id"]:e for e in entry["employee_payroll"]}
        assert set(encoded)==set(by_id)
        for key,r in by_id.items():
            e=encoded[key]
            assert money(e["register_wages"])==money(r["wages_paid"]) and money(e["open_wages"])==pending[key]
            assert {c:money(v) for c,v in e["verified_by_code"].items()}==dict(expected[key])
            for c,value in expected[key].items(): expected_codes[c]+=value
            for part in e["parts"]:
                if pending[key]: assert part["status"]=="OPEN"
        if (directory/"subcontractor-payments.csv").is_file():
            for c,value in added.items(): expected_codes[c]+=value
        expected_rows=[{"class_code":c,"payroll_allocated":f"{v:.2f}","rationale_ref":code_refs[c]} for c,v in sorted(expected_codes.items()) if v]
        assert rows(codes/(directory.name+".csv"))==expected_rows
        assert {c:money(v) for c,v in entry["verified_by_code"].items()}==dict(expected_codes)
        controls["open_wages"]=sum(pending.values(),Decimal("0.00"))
        controls["verified"]=sum(expected_codes.values(),Decimal("0.00"))
        assert controls["register"]+controls["added"]==controls["verified"]+controls["open_wages"]
        assert controls["basis"]==controls["added"]+controls["nonpayroll"]+controls["open_basis"]
        for check in entry["reconciliation"].values():
            if check is not None: assert check["reconciled"] and money(check["difference"])==0
        # Independently read employer-reported amounts, then check every difference.
        reported={}
        for line in (directory/"application.md").read_text().splitlines():
            cells=[c.strip() for c in line.strip().strip("|").split("|")]
            if len(cells)==3 and re.fullmatch(r"[A-Z]-\d+",cells[0]): reported[cells[0]]=money(cells[2].replace(",",""))
        assert reported=={r["class_code"]:money(r["payroll"]) for r in entry["application"]["reported"]}
        for c in set(reported)|set(expected_codes):
            assert money(entry["application"]["verified_differences"].get(c,"0"))==expected_codes.get(c,0)-reported.get(c,0)
        # Verify source bytes/line spans/excerpts and confirmation coverage.
        qs=employer["questions"]; covered=set().union(*(q["covers"] for q in qs))
        assert set(employer["required"])<=covered
        for ref in entry["sources"]:
            raw=Path(ref["source"]).read_bytes(); text=raw.decode("utf-8")
            assert sha(raw)==ref["sha256"] and 1<=ref["line_start"]<=ref["line_end"]<=len(text.splitlines())
            excerpt=ref.get("excerpt","").strip()
            assert not excerpt or " ".join(excerpt.split()) in " ".join(text.split())
            assert "source:"+ref["id"] in covered
            citations+=1
        indexed={(r["source"],tuple(r["values"].items())) for r in employer["records"]}
        for path in directory.glob("*.csv"):
            for raw_row in rows(path):
                assert (str(path),tuple(raw_row.items())) in indexed, (path,raw_row)
        for record in employer["records"]:
            assert record["questions"] and "record:"+record["id"] in covered
            records+=1
        report_section=sections(report_text)[directory.name]
        for proposal in entry["proposals"]:
            assert "**UNAPPROVED — "+proposal["subject"]+"**" in report_section
        summary[directory.name]={"codes":{c:f"{v:.2f}" for c,v in sorted(expected_codes.items())},"controls":{k:f"{v:.2f}" for k,v in controls.items()},"questions":len(qs),"citations":len(entry["sources"]),"records":len(employer["records"])}
        for k,v in controls.items(): portfolio[k]+=v
    assert {p["name"] for p in plan["priorities"]}=={"Severn Homebuilders","Bay Crest Exteriors"}
    for priority in plan["priorities"]:
        assert priority["source"]["locator"]=="Nadia Brennan · 09:18 PM"
        assert priority["reason"] in question_text and priority["reason"] in report_text
    assert not coverage_gaps(plan)
    return {"employers":summary,"portfolio":{k:f"{v:.2f}" for k,v in portfolio.items()},"citations":citations,"records":records,"uncovered":{}}

