    assert subprocess.check_output(["git","branch","--show-current"],cwd=REPO,text=True).strip()=="omega/insurance01-attempt2"
    original_zip=Path("/mnt/c/Users/PC/Downloads/employer-files-20261105T002457Z-1-001.zip")
    with zipfile.ZipFile(original_zip) as archive:
        for path in sorted((INPUTS/"employer-files").glob("*/*")):
            if path.is_file(): assert archive.read(str(path.relative_to(INPUTS)))==path.read_bytes(),str(path)
    assert GUIDE.read_bytes()==Path("/mnt/c/Users/PC/Downloads/classification-guide.md").read_bytes()
    assert INTERVIEW.read_bytes()==Path("/mnt/c/Users/PC/Downloads"/INTERVIEW.name).read_bytes()
    generated=ROOT/"generated"; candidate=ROOT/"candidate"; candidate.mkdir()
    state=generate_csvs(GUIDE,INTERVIEW,all_employers=INPUTS/"employer-files",output_dir=generated/"codes",review_state=generated/"classification-review.json")
    assert state["status"]!="ERROR" and not state["errors"] and not state["processing"]["errors"]
    question_result=generate_questions(generated/"classification-review.json",codes_dir=generated/"codes",output=generated/"audit-questions.md")
    report_result=generate_report(generated/"classification-review.json",codes_dir=generated/"codes",questions=generated/"audit-questions.md",output=generated/"audit-report.md")
    assert not question_result["uncovered"] and not report_result["uncovered"]
    validated_plan=load_report_plan(generated/"classification-review.json",codes_dir=generated/"codes",questions=generated/"audit-questions.md")
    assert not report_coverage_gaps(validated_plan)
    natives=native_results(state)
    canonical=copy.deepcopy(state)
    canonical["review_state"]=str(REPO/"deliverables/classification-review.json")
    for output in canonical["outputs"]: output["path"]=str(REPO/"deliverables/codes"/Path(output["path"]).name)
    canonical_raw=(json.dumps(canonical,indent=2,ensure_ascii=False)+"\n").encode()
    (candidate/"classification-review.json").write_bytes(canonical_raw)
    (candidate/"codes").mkdir()
    for path in (generated/"codes").glob("*.csv"): (candidate/"codes"/path.name).write_bytes(path.read_bytes())
    question_plan=build_question_plan(canonical,natives,read_markdown(GUIDE),read_markdown(INTERVIEW))
    question_bytes=render_questions(question_plan).encode()
    (candidate/"audit-questions.md").write_bytes(question_bytes)
    report_plan=build_report_plan(question_plan,natives)
    report_plan.update(questions_path=str(REPO/"deliverables/audit-questions.md"),questions_link="audit-questions.md",
        protected={REPO/"deliverables/classification-review.json":sha(canonical_raw),REPO/"deliverables/audit-questions.md":sha(question_bytes)})
    report_bytes=render_report(report_plan).encode()
    (candidate/"audit-report.md").write_bytes(report_bytes)
    # Relocation changes paths and dependent hashes only; no business content.
    assert (generated/"audit-questions.md").read_bytes().replace(str(generated).encode(),str(REPO/"deliverables").encode())==question_bytes
    normalized=(generated/"audit-report.md").read_bytes().replace(str(generated).encode(),str(REPO/"deliverables").encode())
    normalized=normalized.replace(sha((generated/"classification-review.json").read_bytes()).encode(),sha(canonical_raw).encode())
    normalized=normalized.replace(sha((generated/"audit-questions.md").read_bytes()).encode(),sha(question_bytes).encode())
    assert normalized==report_bytes
    financial=independent(canonical,question_plan,question_bytes.decode(),report_bytes.decode(),candidate/"codes")
    original_state=json.loads(subprocess.check_output(["git","show",ORIGINAL+":deliverables/classification-review.json"],cwd=REPO))
    before_entries={e["employer"]:e for e in original_state["processing"]["employers"]}
    for e in canonical["processing"]["employers"]:
        if e["employer"]!="severn-homebuilders": assert before_entries[e["employer"]]==e
        else: assert before_entries[e["employer"]]["adjustments"]==e["adjustments"]
    # Every other employer section remains byte-identical, including questions.
    for name in ("audit-questions.md","audit-report.md"):
        old=sections(subprocess.check_output(["git","show",ORIGINAL+":deliverables/"+name],cwd=REPO).decode())
        new=sections((candidate/name).read_text())
        assert set(old)==set(new) and len(old)==6
        for employer in old:
            if employer!="severn-homebuilders": assert old[employer]==new[employer],(name,employer)
    differing=[]
    files=[p for p in candidate.rglob("*") if p.is_file()]
    assert len(files)==9
    for path in files:
        relative="deliverables/"+str(path.relative_to(candidate))
        old=subprocess.check_output(["git","show",ORIGINAL+":"+relative],cwd=REPO)
        if old!=path.read_bytes(): differing.append(relative)
        assert (REPO/relative).read_bytes()==old, "Existing artifact has unreviewed differences"
        assert str(ROOT).encode() not in path.read_bytes(), "Temporary output path leaked"
    expected={"deliverables/codes/severn-homebuilders.csv","deliverables/classification-review.json","deliverables/audit-questions.md","deliverables/audit-report.md"}
    assert set(differing)==expected,("STOP: unexpected artifact differences",differing)
    for name in ("audit-questions.md","audit-report.md"):
        assert (candidate/name).read_bytes().endswith(b"\n") and not (candidate/name).read_bytes().endswith(b"\n\n")
    result={"status":"VALIDATED_BEFORE_REPLACEMENT","changed_artifacts":sorted(differing),"unexpected_differences":[],"unchanged_other_employer_sections":True,"temporary_metadata_relocation_only":True,"question_generation":question_result,"report_generation":report_result,"independent":financial,"candidate_hashes":{str(p.relative_to(candidate)):sha(p.read_bytes()) for p in files}}
    (ROOT/"validation.json").write_text(json.dumps(result,indent=2)+"\n")
    print(json.dumps({"status":result["status"],"changed_artifacts":result["changed_artifacts"],"unexpected_differences":[],"coverage":report_result["coverage"],"independent":financial,"candidate_hashes":result["candidate_hashes"]},indent=2))
if __name__=="__main__": prepare()

