const root=load("omega2_step10_temp");
const script=`import json,re,subprocess,sys
from pathlib import Path
root=Path(sys.argv[1]); candidate=root/"candidate"
state=json.loads((candidate/"classification-review.json").read_text())
entry=next(e for e in state["processing"]["employers"] if e["employer"]=="severn-homebuilders")
marissa=next(e for e in entry["employee_payroll"] if e["employee_id"]=="SH-E06")
refs={r["id"]:r for r in entry["sources"]}
decision=marissa["parts"][0]["decision"]
print(json.dumps({"marissa":{"wages":marissa["register_wages"],"verified_by_code":marissa["verified_by_code"],"open_wages":marissa["open_wages"],"decision":{k:decision[k] for k in ("status","class_code","rationale_ref","reason","required_confirmation")},"rule_sources":[refs[k] for k in decision["rule_sources"]],"source_records":[refs[k] for k in decision["evidence_sources"] if "site-signin" in refs[k]["source"]]},"kent":[{"invoice":l["adjustment_id"],"status":l["status"],"verified":l["payroll_added"],"open":l["unresolved_basis"],"proposal":l["proposal"]} for l in entry["adjustments"]["lines"] if l["status"]=="OPEN"]},indent=2))
for name in ("audit-questions.md","audit-report.md"):
    text=(candidate/name).read_text()
    for match in re.finditer(r"(?ms)^### [^\\n]*(?:Marissa|External site visitors)[^\\n]*\\n.*?(?=^### |^<details>|\\\\Z)",text):
        print(name+" EXCERPT\\n"+match.group(0)[:7500])
`;
const quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
text(await tools.exec_command({cmd:"python3 -B -c "+quote(script)+" "+quote(root),max_output_tokens:4900}));

const b=load("omega2_step10_before"),root=load("omega2_step10_temp");
const script=`import hashlib,json,pathlib,shutil,subprocess,sys
before=json.loads(sys.argv[1]); root=pathlib.Path(sys.argv[2]); repo=pathlib.Path.cwd()
validation=json.loads((root/"validation.json").read_text())
allowed={"deliverables/codes/severn-homebuilders.csv","deliverables/classification-review.json","deliverables/audit-questions.md","deliverables/audit-report.md"}
assert validation["status"]=="VALIDATED_BEFORE_REPLACEMENT" and not validation["unexpected_differences"]
assert set(validation["changed_artifacts"])==allowed
assert subprocess.check_output(["git","branch","--show-current"],text=True).strip()=="omega/insurance01-attempt2"
assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()==before["head"]
assert subprocess.check_output(["git","rev-parse","refs/heads/main"],text=True).strip()==before["main"]
for group in ("files","sources","download_originals"):
    for name,expected in before[group].items():
        p=pathlib.Path(name); s=p.stat()
        assert hashlib.sha256(p.read_bytes()).hexdigest()==expected["sha256"],name
        assert str(s.st_mtime_ns)==expected["mtime_ns"] and s.st_mode==expected["mode"],name
for name,digest in validation["candidate_hashes"].items():
    assert hashlib.sha256((root/"candidate"/name).read_bytes()).hexdigest()==digest,name
backup=root/"before-replacement"
for relative in sorted(allowed):
    saved=backup/relative; saved.parent.mkdir(parents=True,exist_ok=True)
    saved.write_bytes((repo/relative).read_bytes())
for relative in sorted(allowed):
    source=root/"candidate"/pathlib.Path(relative).relative_to("deliverables")
    destination=repo/relative
    destination.write_bytes(source.read_bytes())
    assert destination.read_bytes()==source.read_bytes(),relative
print(json.dumps({"replaced":sorted(allowed),"backup":str(backup),"validated_before_replacement":True},indent=2))
`;
const quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
text(await tools.exec_command({cmd:"python3 -B -c "+quote(script)+" "+quote(JSON.stringify(b))+" "+quote(root),max_output_tokens:1200}));

