const script=`import hashlib,json,pathlib,subprocess,sys
before=json.loads(sys.argv[1]); root=pathlib.Path(sys.argv[2]); changes={}
for category in ("files","sources","download_originals"):
    changes[category]=[]
    for name,expected in before[category].items():
        p=pathlib.Path(name); s=p.stat()
        actual={"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"mtime_ns":str(s.st_mtime_ns),"mode":s.st_mode}
        if actual!=expected: changes[category].append({"path":name,"changed_fields":[k for k in actual if actual[k]!=expected[k]]})
allowed={"deliverables/codes/severn-homebuilders.csv","deliverables/classification-review.json","deliverables/audit-questions.md","deliverables/audit-report.md"}
assert {c["path"] for c in changes["files"]}==allowed
assert not changes["sources"] and not changes["download_originals"]
def git(*args):
    return subprocess.check_output(["git","--no-optional-locks",*args],text=True).strip()
refs=git("for-each-ref","--format=%(refname) %(objectname)","refs/entire","refs/heads/entire")
assert refs==before["entire_refs"]
assert git("rev-parse","HEAD")==before["head"] and git("rev-parse","refs/heads/main")==before["main"]
assert git("branch","--show-current")==before["branch"]
assert not git("diff","--cached","--name-only")
check=subprocess.run(["git","--no-optional-locks","diff","--check"],capture_output=True,text=True)
assert check.returncode==0,(check.stdout,check.stderr)
visible=set(subprocess.check_output(["git","--no-optional-locks","ls-files","-co","--exclude-standard","-z"]).decode().rstrip("\\0").split("\\0"))
assert not (visible-set(before["files"])),sorted(visible-set(before["files"]))
flags={}
def scan(value,prefix):
    if isinstance(value,dict):
        for key,item in value.items():
            if isinstance(item,bool) and any(token in key.casefold() for token in ("push","upload","enabled")): flags[prefix+"."+key]=item
            scan(item,prefix+"."+key)
for name in before["files"]:
    if ".entire/" in name and name.endswith(".json"): scan(json.loads(pathlib.Path(name).read_text()),name)
assert any(value is False for key,value in flags.items() if "push_sessions" in key)
result={"status":"PASS","changed_this_step":changes["files"],"source_records_unchanged":len(before["sources"]),"download_originals_unchanged":len(before["download_originals"]),"preserved_planning_files":len([p for p in before["files"] if p.startswith("docs/")]),"main":git("rev-parse","refs/heads/main"),"head":git("rev-parse","HEAD"),"branch":git("branch","--show-current"),"entire_refs_unchanged":True,"entire_settings_flags":flags,"new_repository_paths":[],"staged_files":[],"diff_check_exit_code":check.returncode,"git_status":git("status","--short")}
(root/"preservation.json").write_text(json.dumps(result,indent=2)+"\\n")
print(json.dumps(result,indent=2))
