const script=`import json
from pathlib import Path
out={}
for f in Path(".git/entire-sessions").glob("*.json"):
    data=json.loads(f.read_text())
    out[str(f)]={"keys":list(data),"metadata":{k:v for k,v in data.items() if any(t in k.lower() for t in ("id","state","status","time","started","ended","exited","base","branch","agent","head","checkpoint","transcript","session","phase")) and not any(t in k.lower() for t in ("prompt","text","message"))}}
print(json.dumps(out,indent=2))
`;
const quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
const results=await Promise.allSettled([
tools.exec_command({cmd:"entire status --json\nentire status --detailed\ngit --no-optional-locks show -s --format='%H%n%B' main\ngit --no-optional-locks ls-tree -r --name-only refs/entire/checkpoints/J7/01M6PH49FR53AABARMSCWB4ZJ7\ngit --no-optional-locks ls-tree -r --name-only refs/heads/entire/a1ace93-e3b0c4","max_output_tokens":2600}),
tools.exec_command({cmd:"python3 -B -c "+quote(script),max_output_tokens:2200}),
tools.exec_command({cmd:"nl -ba skills/class-code-assistant/legal_office_processing.py | sed -n '45,71p'\nnl -ba skills/class-code-assistant/employer_processing.py | sed -n '438,490p'\nrg -n 'Harbor|Marissa|Kent Island|Severn|Bay Crest|Larkspur|Patuxent|Annapolis|SH-E|BC-E|LL-E|PE-E|AC-E|HP-E' skills/class-code-assistant -g '*.py' -g '!tests/**' -g '!**/tests/**'","max_output_tokens":2300})
]);results.forEach((r,i)=>text({i,...(r.status==="fulfilled"?r.value:{error:String(r.reason)})}));

