const root=load("omega2_step11_before").temp;
const script=`import json,os,subprocess
from pathlib import Path
repo=Path.cwd(); state_path=repo/".git/entire-sessions/01a1a9a5-25d0-7061-94e6-36bd7901e7e2.json"
state=json.loads(state_path.read_text()); owner=state.get("owner",{})
checkpoint_ref="refs/entire/checkpoints/J7/01M6PH49FR53AABARMSCWB4ZJ7"
shadow_ref="refs/heads/entire/a1ace93-e3b0c4"
def git(*args): return subprocess.check_output(["git","--no-optional-locks",*args])
def metadata(blob):
    d=json.loads(git("show",blob))
    allowed={"checkpoint_id","session_id","agent","agent_type","created_at","created","timestamp","commit","commit_hash","base_commit","branch","cli_version","strategy","session_count"}
    return {"keys":list(d),"fields":{k:v for k,v in d.items() if k in allowed}}
shadow_names=git("ls-tree","-r","--name-only",shadow_ref).decode().splitlines()
artifact_names=[str(p.relative_to(repo)) for p in (repo/"deliverables").rglob("*") if p.is_file()]
captured={name:git("show",shadow_ref+":"+name)==(repo/name).read_bytes() for name in artifact_names}
transcript=Path(state["transcript_path"])
with transcript.open("rb") as stream:
    size=transcript.stat().st_size; stream.seek(max(0,size-4*1024*1024)); tail=stream.read()
session_id=state["session_id"]
snapshot_transcript=".entire/metadata/"+session_id+"/full.jsonl"
snapshot_size=int(git("cat-file","-s",shadow_ref+":"+snapshot_transcript))
owner_pid=owner.get("pid")
logs=[{"path":str(p.relative_to(repo)),"bytes":p.stat().st_size} for p in (repo/".entire/logs").glob("*") if p.is_file()]
out={"version":"0.11.3","checkpoint_ref":checkpoint_ref,"checkpoint_object":git("rev-parse",checkpoint_ref).decode().strip(),"checkpoint_metadata":metadata(checkpoint_ref+":metadata.json"),"checkpoint_session_metadata":metadata(checkpoint_ref+":0/metadata.json"),
"shadow_ref":shadow_ref,"shadow_object":git("rev-parse",shadow_ref).decode().strip(),"shadow_latest_commit":git("log","-1","--format=%H %cI %s",shadow_ref).decode().strip(),
"shadow_contains_current_artifacts":captured,"shadow_transcript_bytes":snapshot_size,
"session":{"id":session_id,"phase":state["phase"],"branch":state["branch"],"last_interaction_time":state["last_interaction_time"],"checkpoint_count":state["checkpoint_count"],"session_turn_count":state["session_turn_count"],"source_transcript_exists":transcript.is_file(),"source_transcript_bytes":size,"source_transcript_tail_has_step10":b"STEP 10: CONTROLLED DELIVERABLE REFRESH" in tail,"source_transcript_tail_has_step11":b"STEP 11: FINAL GENERALIZATION" in tail},
"liveness":{"recorded_owner_pid":owner_pid,"recorded_owner_proc_visible":Path("/proc/"+str(owner_pid)).exists(),"recorded_owner_boot_matches_current":owner.get("boot")==Path("/proc/sys/kernel/random/boot_id").read_text().strip(),"inspection_pid_namespace":os.readlink("/proc/self/ns/pid"),"pid1_comm":Path("/proc/1/comm").read_text().strip(),"pid1_namespace_ids":[v.strip() for v in Path("/proc/1/status").read_text().splitlines() if v.startswith("NSpid:")]},
"log_files":logs}
print(json.dumps(out,indent=2))
Path("${root}/entire-inspection.json").write_text(json.dumps(out,indent=2)+"\\n")
`;
