const root=load("omega2_step11_before").temp;
const script=`import hashlib,json,re,subprocess,sys
from pathlib import Path
root=Path(sys.argv[1]); repo=Path.cwd()
result=json.loads((root/"generalization.json").read_text())
report={"generalization":result["summary"],"failures":[{"case":r["case"],"employees":r["employees"],"actual":r["actual"]} for r in result["results"] if r["status"]=="FAIL"]}
# Search production modules for original identities and payroll-answer literals.
inputs=Path("/home/maxg/insurance01-inputs/employer-files")
terms=set()
for directory in inputs.iterdir():
    if not directory.is_dir(): continue
    terms.add(directory.name)
    import csv
    with (directory/"payroll-register.csv").open() as stream:
        for row in csv.DictReader(stream):
            terms.update((row["employee_id"],row["name"],row["wages_paid"]))
    p=directory/"subcontractor-payments.csv"
    if p.exists():
        with p.open() as stream:
            for row in csv.DictReader(stream): terms.add(row["subcontractor"])
hits=[]
for path in (repo/"skills/class-code-assistant").glob("*.py"):
    text=path.read_text()
    for term in terms:
        if term.casefold() in text.casefold(): hits.append({"file":str(path.relative_to(repo)),"term":term})
