const b=load("omega2_step11_before");
const step10=load("omega2_step10_verified").temporaryDirectory;
const script=`import csv,hashlib,json,pathlib,re,subprocess,sys
before=json.loads(sys.argv[1]); previous=pathlib.Path(sys.argv[2]); root=pathlib.Path(before["temp"])
def info(p):
    s=p.stat();return {"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"mtime_ns":str(s.st_mtime_ns),"mode":s.st_mode}
changed={}
for category in ("files","sources","download_originals"):
    changed[category]=[name for name,expected in before[category].items() if info(pathlib.Path(name))!=expected]
    assert not changed[category],(category,changed[category])
runtime=[]
for name,expected in before["capture_files"].items():
    p=pathlib.Path(name)
    if info(p)==expected: continue
