const script=`import json
from pathlib import Path
logs=[json.loads(line) for line in Path(".entire/logs/entire.log").read_text().splitlines()]
rows=[d for d in logs if "2026-11-06T10:53:3" in d.get("time","")]
print(json.dumps([{"keys":list(d),**{k:d[k] for k in ("time","level","msg","component","event","files_touched","files","attribution_count","error") if k in d}} for d in rows],indent=2))
`;
const quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
text(await tools.exec_command({cmd:"python3 -B -c "+quote(script),max_output_tokens:900}));

const b=load("omega2_step12_before"),step10=load("omega2_step10_verified").temporaryDirectory;
const script=`import hashlib,json,pathlib,subprocess,sys
b=json.loads(sys.argv[1]); prior=pathlib.Path(sys.argv[2]); root=pathlib.Path(b["temp"])
def info(p):
    s=p.stat();return {"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"mtime_ns":str(s.st_mtime_ns),"mode":s.st_mode}
changed={}
for category in ("files","sources","download_originals"):
    changed[category]=[p for p,expected in b[category].items() if info(pathlib.Path(p))!=expected]
allowed={"skills/class-code-assistant/employer_processing.py","skills/class-code-assistant/tests/test_employer_processing.py"}
assert set(changed["files"])==allowed,changed["files"]
assert not changed["sources"] and not changed["download_originals"]
runtime=[]
for name,expected in b["capture_files"].items():
    p=pathlib.Path(name)
    if info(p)==expected: continue
    if name==".entire/logs/entire.log":
        digest=hashlib.sha256();found=False
        for line in p.read_bytes().splitlines(keepends=True):
            digest.update(line)
            if digest.hexdigest()==expected["sha256"]:found=True;break
        assert found,"Previous operational log bytes must remain intact"
        runtime.append({"path":name,"change":"normal log append","original_prefix_preserved":True})
    elif name==".git/entire-sessions/01a1a9a5-25d0-7061-94e6-36bd7901e7e2.json":
        state=json.loads(p.read_text())
        assert state["session_id"]=="01a1a9a5-25d0-7061-94e6-36bd7901e7e2"
        assert state["base_commit"]==b["head"] and state["branch"]==b["branch"] and state["phase"]=="active"
        assert pathlib.Path(state["transcript_path"]).is_file()
        runtime.append({"path":name,"change":"live session metadata updated by normal capture","session_identity_branch_base_and_transcript_retained":True,"checkpoint_count":state["checkpoint_count"]})
    else:raise AssertionError(("Unexpected capture change",name))
def git(*args):return subprocess.check_output(["git","--no-optional-locks",*args],text=True).strip()
assert git("branch","--show-current")==b["branch"]=="omega/insurance01-attempt2"
assert git("rev-parse","HEAD")==git("rev-parse","main")==b["head"]==b["main"]
assert git("for-each-ref","--format=%(refname) %(objectname)","refs/entire","refs/heads/entire")==b["entire_refs"]
assert not git("diff","--cached","--name-only") and not git("log","--oneline","main..HEAD")
visible=set(subprocess.check_output(["git","--no-optional-locks","ls-files","-co","--exclude-standard","-z"]).decode().rstrip("\\0").split("\\0"))
assert not visible-set(b["files"])
check=subprocess.run(["git","--no-optional-locks","diff","--check"],capture_output=True,text=True)
assert check.returncode==0,(check.stdout,check.stderr)
artifacts=json.loads((prior/"validation.json").read_text())["candidate_hashes"]
for name,sha in artifacts.items():assert hashlib.sha256((pathlib.Path("deliverables")/name).read_bytes()).hexdigest()==sha,name
synthetic=json.loads((root/"final-synthetic/generalization.json").read_text())
original=json.loads(pathlib.Path("/tmp/insurance01-step11-6b25c9nh/generalization.json").read_text())
assert synthetic["summary"]=={"cases":14,"passed":11,"failed":3,"errors":0}
failures=[v for v in synthetic["results"] if v["status"]=="FAIL"]
assert {v["case"] for v in failures}=={"04-equivalent-estimator-prose","05-equivalent-business-prose","14-equivalent-legal-prose"}
for v in failures:assert v["actual"]==next(o for o in original["results"] if o["case"]==v["case"])["actual"]
assert (root/"final-synthetic/generalization.py").read_bytes()==pathlib.Path("/tmp/insurance01-step11-6b25c9nh/generalization.py").read_bytes()
case=next(v for v in synthetic["results"] if v["case"]=="12-conflicting-individual-duties")
assert case["status"]=="PASS" and case["actual"]=={"codes":{"F-710":"60.00"},"open_wages":"40.00","open_adjustment_basis":"0.00"}
settings=json.loads(pathlib.Path(".entire/settings.local.json").read_text())
assert settings["enabled"] and settings["strategy_options"]["push_sessions"] is False
result={"changed_this_step":changed["files"],"source_changes":[],"download_original_changes":[],"all_nine_deliverables_unchanged":len(artifacts)==9,"planning_files_preserved":len([p for p in b["files"] if p.startswith("docs/")]),"interviews_preserved":True,"main_and_head":b["head"],"branch":b["branch"],"omega_code_commits":0,"staged_files":[],"entire_refs_settings_and_captured_transcripts_preserved":True,"automatic_uploads_disabled":True,"automatic_capture_runtime_updates":runtime,"diff_check_exit_code":check.returncode,"synthetic":synthetic["summary"],"deferred_failures":[{"case":v["case"],"open_wages":v["actual"]["open_wages"]} for v in failures],"synthetic_expectations_unchanged":True,"git_status":git("status","--short")}
(root/"preservation.json").write_text(json.dumps(result,indent=2)+"\\n")
print(json.dumps(result,indent=2))
`;
const quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
const r=await tools.exec_command({cmd:"python3 -B -c "+quote(script)+" "+quote(JSON.stringify(b))+" "+quote(step10),max_output_tokens:2300});text(r);if(r.exit_code===0)store("omega2_step12_preservation",JSON.parse(r.output));else throw Error("Preservation audit requires investigation");
store("omega2_step12_verified",{...load("omega2_step12_verified"),preservationVerified:true,entireRuntimeNote:"Normal capture updated the live session metadata and appended logs; checkpoint refs/settings and existing transcripts unchanged.",fullSuite:{command:"python3 -B -m unittest discover -s skills/class-code-assistant/tests",passed:366,failures:0,errors:0,skips:0,seconds:47.228}});

