const b=load("omega2_step13_before"),quote=s=>"'"+s.replace(/'/g,"'\"'\"'")+"'";
const script=`import hashlib,json,pathlib,subprocess,sys
b=json.loads(sys.argv[1]);root=pathlib.Path(b["temp"])
def info(p):
    s=p.stat();return {"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"mtime_ns":str(s.st_mtime_ns),"mode":s.st_mode}
changed={}
for category in ("files","sources","originals"):
    changed[category]=[p for p,v in b[category].items() if info(pathlib.Path(p))!=v]
allowed={"skills/class-code-assistant/employer_processing.py","skills/class-code-assistant/tests/test_homebuilding_processing.py"}
assert set(changed["files"])==allowed,changed
assert not changed["sources"] and not changed["originals"]
runtime=[]
for name,v in b["capture"].items():
    p=pathlib.Path(name)
    if info(p)==v:continue
    if name==".entire/logs/entire.log":
        digest=hashlib.sha256();found=False
        for line in p.read_bytes().splitlines(keepends=True):
            digest.update(line)
            if digest.hexdigest()==v["sha256"]:found=True;break
        assert found,"Original operational log prefix changed"
        runtime.append({"path":name,"normal_log_append":True,"original_prefix_preserved":True})
    elif name==".git/entire-sessions/01a1a9a5-25d0-7061-94e6-36bd7901e7e2.json":
        s=json.loads(p.read_text())
        assert s["session_id"]=="01a1a9a5-25d0-7061-94e6-36bd7901e7e2"
        assert s["branch"]==b["branch"] and s["base_commit"]==b["head"] and s["phase"]=="active"
        assert pathlib.Path(s["transcript_path"]).is_file()
        runtime.append({"path":name,"normal_live_metadata_update":True,"session_identity_and_transcript_retained":True})
    else:raise AssertionError(("Unexpected capture file change",name))
def git(*a):return subprocess.check_output(["git","--no-optional-locks",*a],text=True).strip()
assert git("branch","--show-current")==b["branch"]=="omega/insurance01-attempt2"
assert git("rev-parse","HEAD")==git("rev-parse","main")==b["head"]==b["main"]
assert git("for-each-ref","--format=%(refname) %(objectname)","refs/entire","refs/heads/entire")==b["refs"]
assert not git("diff","--cached","--name-only") and not git("log","--oneline","main..HEAD")
visible=set(subprocess.check_output(["git","--no-optional-locks","ls-files","-co","--exclude-standard","-z"]).decode().rstrip("\\0").split("\\0"))
assert not (visible-set(b["files"]))
check=subprocess.run(["git","--no-optional-locks","diff","--check"],capture_output=True,text=True)
assert check.returncode==0,(check.stdout,check.stderr)
artifacts=[p for p in pathlib.Path("deliverables").rglob("*") if p.is_file()]
assert len(artifacts)==9
assert all(info(p)==b["files"][str(p)] for p in artifacts)
s=json.loads((root/"generalization.json").read_text())
original=json.loads(pathlib.Path("/tmp/insurance01-step11-6b25c9nh/generalization.json").read_text())
assert (root/"generalization.py").read_bytes()==pathlib.Path("/tmp/insurance01-step11-6b25c9nh/generalization.py").read_bytes()
assert s["summary"]=={"cases":14,"passed":12,"failed":2,"errors":0}
failures=[r for r in s["results"] if r["status"]=="FAIL"]
assert {r["case"] for r in failures}=={"04-equivalent-estimator-prose","14-equivalent-legal-prose"}
for r in failures:assert r["actual"]==next(o for o in original["results"] if o["case"]==r["case"])["actual"]
fixed=next(r for r in s["results"] if r["case"]=="05-equivalent-business-prose")
assert fixed["status"]=="PASS" and fixed["actual"]=={"codes":{"C-110":"100.06","H-420":"150.04"},"open_wages":"0.00","open_adjustment_basis":"0.00"}
settings=json.loads(pathlib.Path(".entire/settings.local.json").read_text())
assert settings["enabled"] and settings["strategy_options"]["push_sessions"] is False
result={"status":"PASS","changed_this_step":changed["files"],"all_nine_artifacts_unchanged":True,"source_files_unchanged":len(b["sources"]),"download_originals_unchanged":len(b["originals"]),"planning_files_preserved":len([p for p in b["files"] if p.startswith("docs/")]),"interviews_preserved":True,"main_and_head":b["head"],"branch":b["branch"],"staged_files":[],"omega_commits":0,"entire_refs_settings_and_captured_transcripts_preserved":True,"automatic_uploads_disabled":True,"automatic_capture_runtime_updates":runtime,"diff_check_exit_code":check.returncode,"synthetic":s["summary"],"corrected_case":fixed["actual"],"remaining_failures":[{"case":r["case"],"open_wages":r["actual"]["open_wages"]} for r in failures],"git_status":git("status","--short")}
(root/"verification.json").write_text(json.dumps(result,indent=2)+"\\n")
print(json.dumps(result,indent=2))
`;
const r=await tools.exec_command({cmd:"python3 -B -c "+quote(script)+" "+quote(JSON.stringify(b)),max_output_tokens:2300});text(r);if(r.exit_code===0)store("omega2_step13_preservation",JSON.parse(r.output));else throw Error("Preservation audit failed; stop for investigation");
