python3 -B -c 'import hashlib,json,subprocess
from pathlib import Path
root=Path("/tmp/insurance01-step15-9mdsjx7p")
before=json.loads((root/"before.json").read_text())
def snap(p):
 p=Path(p);s=p.stat()
 return {"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"mtime_ns":str(s.st_mtime_ns),"mode":s.st_mode}
def git(*args): return subprocess.check_output(["git","--no-optional-locks",*args],text=True).strip()
changed={group:[p for p,old in before[group].items() if not Path(p).is_file() or snap(p)!=old] for group in ("files","sources","originals","capture")}
visible=set(p for p in subprocess.check_output(["git","--no-optional-locks","ls-files","-co","--exclude-standard","-z"]).decode().split("\0") if p)
known=set(before["files"])
additional=sorted(visible-known)
runtime=[]
unexpected_capture=[]
for p in changed["capture"]:
 if not Path(p).is_file():
  unexpected_capture.append(p);continue
 if p==".entire/logs/entire.log":
  h=hashlib.sha256();append_only=False
  for line in Path(p).read_bytes().splitlines(keepends=True):
   h.update(line)
   if h.hexdigest()==before["capture"][p]["sha256"]:append_only=True;break
