paths=git("ls-tree","-r","--name-only",base,"skills/class-code-assistant").decode().splitlines()
modules={Path(p).stem:p for p in paths if p.endswith(".py") and Path(p).parent.as_posix()=="skills/class-code-assistant"}
class GitModules(importlib.abc.MetaPathFinder,importlib.abc.Loader):
 def find_spec(self,fullname,path=None,target=None):
  return importlib.util.spec_from_loader(fullname,self) if fullname in modules else None
 def create_module(self,spec):return None
 def exec_module(self,module):
  path=modules[module.__name__]
  module.__file__=str(Path(path).absolute())
  exec(compile(git("show",base+":"+path),module.__file__,"exec"),module.__dict__)
sys.meta_path.insert(0,GitModules())
from employer_processing import process_employer
original=0
for p in paths:
 if Path(p).name.startswith("test_") and p.endswith(".py"):
  original+=sum(isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith("test_") for n in ast.walk(ast.parse(git("show",base+":"+p))))
current=sum(isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith("test_") for p in Path("skills/class-code-assistant/tests").glob("test_*.py") for n in ast.walk(ast.parse(p.read_text())))
root=Path("/tmp/insurance01-step11-6b25c9nh")
scenarios=json.loads((root/"generalization.json").read_text())["results"]
results=[]
for case in scenarios:
 folder=root/"employers"/case["case"]
 try:
  r=process_employer("/home/maxg/insurance01-inputs/classification-guide.md",folder,Path("interviews/ch03-premium-audit-20261105-0222(1).md"))
