  results.append({"case":case["case"],"status":"PASS" if actual==case["expected"] and r.independent_reconciliation.reconciled else "FAIL","actual":actual})
 except Exception as exc:results.append({"case":case["case"],"status":"ERROR","error":str(exc)})
print(json.dumps({"original_revision":base,"test_method_counts":{"original":original,"current":current},"original_revision_generalization":{"passed":sum(r["status"]=="PASS"for r in results),"failed":sum(r["status"]=="FAIL"for r in results),"errors":sum(r["status"]=="ERROR"for r in results)},"results":results},indent=2))
`;
